import random

def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    # Recency-weighted updates: recent actions have more impact
    recency = 1.0 / max(1, round_num / 5 + 1)
    if action == 'cooperate':
        new_reputation = min(current_reputation + 0.3 * recency, 1.0)
    else:
        new_reputation = max(current_reputation - 0.3 * recency, -1.0)
    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    # Check if opponent recently defected on us
    if len(my_history) >= 2:
        prev_opponent = my_history[-2].get('action')
        if prev_opponent == 'defect':
            # Retaliate after being defected against
            return False

    # Threshold-based cooperation with moderate exploration
    if recipient_reputation > 0.5:
        return True
    elif recipient_reputation < -0.5:
        return False
    else:
        # Middle ground: cooperate based on reputation signal
        cooperate_prob = (recipient_reputation + 1.0) / 2.0
        cooperate_prob = max(0.2, min(0.8, cooperate_prob))
        return random.random() < cooperate_prob
